CREATE TABLE order_items (
    id INT,
    item_name VARCHAR(50),
    unit_price NUMERIC(10, 2),
    quantity INT
);
INSERT INTO order_items VALUES (1, 'Server Rack', 250.00, 4);

SELECT item_name, unit_price * quantity AS subtotal
FROM order_items;

CREATE TABLE clients (
    id INT,
    name VARCHAR(50),
    phone VARCHAR(20),
    email VARCHAR(50)
);
INSERT INTO clients VALUES 
(1, 'Alice', NULL, 'alice@work.test'),
(2, 'Bob', '555-0199', NULL),
(3, 'Charlie', NULL, NULL);

SELECT name, COALESCE(phone, email, 'No contact provided') AS primary_contact
FROM clients;

CREATE TABLE employees (
    id INT,
    name VARCHAR(50),
    salary INT
);
INSERT INTO employees VALUES (1, 'Ana', 85000), (2, 'Ravi', 50000), (3, 'Sam', 35000);

SELECT name, salary,
    CASE 
        WHEN salary >= 80000 THEN 'Senior / Lead'
        WHEN salary >= 45000 THEN 'Mid-Level'
        ELSE 'Junior'
    END AS tier
FROM employees;
